import { AbstractShareable, BaseClientOptions, ChannelStatistics, } from '../types/index.js';
import { CHANNEL_STATUS_MAP } from '../const/index.js';
export class DefaultChannelLoadBalancer {
    constructor() { }
    async getChannel(name, channels) {
        // 按优先级分组并排序
        const priorityGroups = this.groupByPriority(channels);
        // 按优先级降序选择可用组
        for (const group of priorityGroups) {
            const availableChannels = group.filter(c => c.status === 'enabled');
            if (availableChannels.length > 0) {
                return this.selectByWeight(availableChannels);
            }
        }
        throw new Error('No available channels');
    }
    // 按优先级分组并降序排列
    groupByPriority(channels) {
        const priorityMap = new Map();
        channels.forEach(channel => {
            const group = priorityMap.get(channel.priority) || [];
            group.push(channel);
            priorityMap.set(channel.priority, group);
        });
        return Array.from(priorityMap.keys())
            .sort((a, b) => b - a) // 降序排列
            .map(priority => priorityMap.get(priority));
    }
    // 在相同优先级内按权重选择
    selectByWeight(channels) {
        const totalWeight = channels.reduce((sum, c) => sum + c.weight, 0);
        let random = Math.random() * totalWeight;
        for (const channel of channels) {
            random -= channel.weight;
            if (random <= 0) {
                return channel;
            }
        }
        return channels[0];
    }
    /**
     * 获取渠道列表及其分配的数量
     * generated by qwen-2.5-max
     *
     * @param modelName 模型名称
     * @param channels 渠道列表
     * @param totalQuantity 总数量
     * @returns 返回一个包含渠道及其分配数量的数组
     */
    async getChannels(modelName, channels, totalQuantity) {
        // 筛选出支持该模型的渠道
        const supportedChannels = channels.filter(channel => channel.models.some(m => m.name === modelName));
        if (supportedChannels.length === 0) {
            throw new Error('No channels support the specified model');
        }
        // 按优先级分组并排序
        const priorityGroups = this.groupByPriority(supportedChannels);
        // 只选择优先级最高的组
        const highestPriorityGroup = priorityGroups[0];
        if (!highestPriorityGroup || highestPriorityGroup.length === 0) {
            throw new Error('No available channels with the highest priority');
        }
        // 计算总权重
        const totalWeight = highestPriorityGroup.reduce((sum, c) => sum + c.weight, 0);
        // 根据权重分配数量
        const result = [];
        let remainingQuantity = totalQuantity;
        for (const channel of highestPriorityGroup) {
            const allocatedQuantity = Math.floor((channel.weight / totalWeight) * totalQuantity);
            result.push({ channel, quantity: allocatedQuantity });
            remainingQuantity -= allocatedQuantity;
        }
        // 将剩余的数量分配给第一个渠道（避免因取整导致数量不足）
        if (remainingQuantity > 0 && result.length > 0) {
            result[0].quantity += remainingQuantity;
        }
        return result;
    }
}
/**
 * 渠道
 * 每个渠道对应一个adapter，并记录客户端的options
 */
export class Channel extends AbstractShareable {
    constructor(params) {
        super(params);
        this.modelType = 'settings';
        this.models = (params.models || []).map((m) => typeof m === 'string' ? { name: m, features: ['chat', 'tool'] } : m);
        if (params.adapterType) {
            this.adapterType = params.adapterType;
        }
        if (params.options) {
            this.options = new BaseClientOptions().fromString(JSON.stringify(params.options));
        }
        this.weight = params.weight || 1;
        this.priority = params.priority || 1;
        this.status = params.status || 'enabled';
        this.disabledReason = params.disabledReason;
        this.statistics = params.statistics || new ChannelStatistics();
        this.init();
    }
    async init() {
        if (this.options) {
            return this.options.ready();
        }
    }
    async ready() {
        await this.init();
    }
    getOptionsForModel(modelName) {
        const modelConfig = this.models.find(model => model.name === modelName);
        return BaseClientOptions.create({
            ...this.options,
            features: modelConfig?.features || this.options.features || [],
        });
    }
    fromString(str) {
        const channel = JSON.parse(str);
        return new Channel(channel);
    }
    toString() {
        const toJsonStr = {
            id: this.id,
            models: this.models.map(m => ({ name: m.name, features: m.features })),
            adapterType: this.adapterType,
            options: this.options.toString(),
            name: this.name,
            type: this.type,
            weight: this.weight,
            statistics: this.statistics.toString(),
            status: this.status,
            priority: this.priority,
            disabledReason: this.disabledReason,
        };
        return JSON.stringify(toJsonStr);
    }
    toFormatedString(verbose = false) {
        let base = `渠道ID：${this.id}\n渠道名称：${this.name}`;
        if (this.adapterType) {
            base += `\n渠道类型：${this.adapterType}`;
        }
        if (this.status) {
            base += `\n渠道状态：${CHANNEL_STATUS_MAP[this.status]}`;
        }
        if (this.weight) {
            base += `\n渠道权重：${this.weight}`;
        }
        if (this.priority) {
            base += `\n渠道优先级：${this.priority}`;
        }
        if (this.disabledReason) {
            base += `\n渠道禁用原因：${this.disabledReason}`;
        }
        if (this.models && this.models.length > 0) {
            base += `\n支持模型：${this.models.map(m => m.name).join(', ')}`;
        }
        if (verbose) {
            if (this.options?.baseUrl) {
                base += `\nBaseURL: ${this.options.baseUrl}`;
            }
            if (this.options?.apiKey) {
                const apiKeyStr = Array.isArray(this.options.apiKey) ? this.options.apiKey.join(',') : this.options.apiKey;
                if (apiKeyStr) {
                    base += `\nAPI Key：${apiKeyStr}`;
                }
            }
        }
        if (this.createdAt) {
            base += `\n创建时间：${this.createdAt}`;
        }
        if (this.updatedAt) {
            base += `\n最后更新时间：${this.updatedAt}`;
        }
        if (this.uploader?.username) {
            base += `\n上传者：@${this.uploader.username}`;
        }
        return base.trimEnd();
    }
}
